 const deleteWorkout=async(workout:Workout)=>{const latest=currentData.current;const after=latest.workouts.map(w=>w.id===workout.id?{...w,status:'deleted' as const,updatedAt:new Date().toISOString()}:w);const adjustment=activityEconomyAdjustment(normalizeGame(latest.game),latest.workouts,after,profile);const explanation=`Al eliminar se ajustarán ${number(adjustment.xpDelta)} XP y ${number(adjustment.balanceDelta)} créditos.${adjustment.deficitAfter?` Quedará un ajuste pendiente de ${number(adjustment.deficitAfter)} créditos por actividad eliminada; las próximas ganancias lo compensarán.`:''} Las cargas usadas no se devuelven.`;if(!window.confirm(`¿Eliminar «${workout.name}» del ${dateLabel(workout.date)}? ${explanation}`))return;try{await persistData({...latest,workouts:after});setScreen('calendar')}catch{setMessage('El borrado sigue pendiente de guardar. Reintenta o exporta tus datos.')}};
