 const restoreRoute=(hash:string)=>{const params=new URLSearchParams(hash.replace(/^#/,''));const view=params.get('view') as Screen|null;const allowed:Screen[]=['summary','calendar','routines','start','editor','routine','settings','detail','progress','game','catalog'];if(!view||!allowed.includes(view)){setScreen('summary');return}const id=params.get('id');if(view==='editor'){const found=currentData.current.workouts.find(w=>w.id===id&&w.status==='draft');if(found)continueDraft(found.id);else setScreen('summary');return}if(view==='routine'){const recovery=currentData.current.routineDraft;if(recovery?.id===id)beginRoutine({...recovery,exercises:recovery.exercises.map(item=>({...item,sets:item.sets??NaN}))},true);else{const found=currentData.current.routines.find(r=>r.id===id);if(found)beginRoutine(structuredClone(found));else setScreen('routines')}return}if(view==='detail'){if(currentData.current.workouts.some(w=>w.id===id&&w.status==='finished')){setDetailId(id);setScreen('detail')}else setScreen('calendar');return}if(view==='progress')setProgressId(id);if(view==='calendar'){const date=params.get('date');if(date&&isCivilDate(date)){setSelectedDate(date);setMonth(`${date.slice(0,7)}-01`)}}if(view==='game'){const tab=params.get('tab');if(['goals','body','crates','collection','ascent'].includes(tab??''))setGameTab(tab as GameTab)}setScreen(view)};
